class Solution {
  public TreeNode upsideDownBinaryTree(TreeNode root) {
    // walk down the left spine; each left child becomes the parent of its old parent and sibling
    TreeNode cur = root, parent = null, parentRight = null;
    while (cur != null) {
      TreeNode left = cur.left, right = cur.right;
      cur.left = parentRight;
      cur.right = parent;
      parent = cur;
      parentRight = right;
      cur = left;
    }
    return parent;
  }
}
